 * Walks one tenant's projects, issues and comments and re-applies the index
 * writers to every row, page by page. Afterwards any indexed document of this
 * org that the walk did not leave in place (archived, deleted, orphaned) is
 * removed. Scoped to a single org on purpose: a full-fleet reindex is a
 * sequence of these, so one slow tenant cannot stall the rest.
 *
 * Archived rows are read too: the index writers own the "is this searchable?"
 * decision, so the job hands every row to them.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    const keep = new Set<string>();
    let complete = true;

    const record = async (
      kind: SearchSubjectKind,
      id: string,
      write: () => Promise<boolean>,
      what: string,
    ): Promise<void> => {
      try {
        if (await write()) keep.add(`${kind}:${id}`);
        result.processed += 1;
      } catch (error) {
        // Unknown outcome: leave whatever is indexed for it untouched.
        keep.add(`${kind}:${id}`);
        result.failed += 1;
        logger.error(`failed to index ${what}`, {
          [`${what}Id`]: id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    };

    let projectCursor: string | null = null;
    do {
      const projects = await projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor: projectCursor,
        includeArchived: true,
      });
      for (const project of projects.items) {
        await record("project", project.id, () => indexProject(orgId, project), "project");
      }
      projectCursor = projects.nextCursor;
    } while (projectCursor);

    let issueCursor: string | null = null;
    do {
      const issues = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: issueCursor,
        includeArchived: true,
      });

      for (const issue of issues.items) {
        await record("issue", issue.id, () => indexIssue(orgId, issue), "issue");

        let commentCursor: string | null = null;
        try {
          do {
            const comments = await commentRepo.listComments({
              orgId,
              issueId: issue.id,
              includeArchived: true,
              limit: PAGE_SIZE,
              cursor: commentCursor,
            });
            for (const comment of comments.items) {
              await record(
                "comment",
                comment.id,
                () => indexComment(orgId, comment),
                "comment",
              );
            }
            commentCursor = comments.nextCursor;
          } while (commentCursor);
        } catch (error) {
          complete = false;
          result.failed += 1;
          logger.error("failed to list comments", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
      issueCursor = issues.nextCursor;
    } while (issueCursor);

    if (!complete) return;

    for (const doc of await searchRepo.listIndexedKeys(orgId)) {
      if (keep.has(`${doc.subjectKind}:${doc.subjectId}`)) continue;
      await searchRepo.deleteSearchDocument(orgId, doc.subjectKind, doc.subjectId);
    }
  });
}
